def is_not_prime(n):
    """
    Returns True if n is not a prime number, False otherwise.
    """
    if n <= 1:
        return True
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


assert is_not_prime(2) == False, "is_not_prime(2) should be False"
assert is_not_prime(10) == True, "is_not_prime(10) should be True"
assert is_not_prime(35) == True, "is_not_prime(35) should be True"
assert is_not_prime(37) == False, "is_not_prime(37) should be False"

def find_char_long(s: str) -> set:
    """
    Returns a set of all words in the string that are at least 4 characters long.
    """
    return set(word for word in s.split() if len(word) >= 4)

def square_perimeter(side_length: int) -> int:
    """Return the perimeter of a square given its side length."""
    return side_length * 4

def is_Monotonic(arr):
    if len(arr) < 2:
        return True

    # Check if the array is non-decreasing
    for i in range(1, len(arr)):
        if arr[i] < arr[i-1]:
            return False

    # Check if the array is non-increasing
    for i in range(1, len(arr)):
        if arr[i] > arr[i-1]:
            return False

    return True

# Test cases
assert is_Monotonic([6, 5, 4, 4]) == True
assert is_Monotonic([1, 2, 2, 3]) == True
assert is_Monotonic([1, 3, 2]) == False

def merge_dictionaries_three(d1, d2, d3):
    """
    Merge three dictionaries into a single dictionary.
    The order of keys in the result depends on the order they are first encountered.
    """
    result = {}

    # Iterate through all dictionaries to collect keys
    for key in d1.keys() + d2.keys() + d3.keys():
        if key in d1:
            result[key] = d1[key]
        elif key in d2:
            result[key] = d2[key]
        elif key in d3:
            result[key] = d3[key]

    return result

def freq_count(lst):
    """
    Get the frequency of all elements in a list as a dictionary.

    Parameters:
    lst (list): A list of integers

    Returns:
    dict: A dictionary mapping each element to its frequency

    Examples:
    >>> freq_count([10,10,10,10,20,20,20,20,40,40,50,50,30])
    {10: 4, 20: 4, 40: 2, 50: 2, 30: 1}
    >>> freq_count([1,2,3,4,3,2,4,1,3,1,4])
    {1: 3, 2: 2, 3: 3, 4: 3}
    >>> freq_count([5,6,7,4,9,10,4,5,6,7,9,5])
    {10: 1, 5: 3, 6: 2, 7: 2, 4: 2, 9: 2}
    """
    freq = {}
    for num in lst:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1
    return freq

def closest_num(n: int) -> int:
    """Return the smallest integer strictly less than n."""
    return n - 1

def power(a, b):
    """Calculate a to the power of b."""
    return a ** b

def frequency_lists(flattened_list):
    """
    Find the frequency of each element in a flattened list of lists.

    Parameters:
    flattened_list (list of list): A list where each inner list contains integers.

    Returns:
    dict: A dictionary mapping each integer to its frequency.
    """
    frequency = {}

    # Flatten the list and count occurrences
    for item in flattened_list:
        for num in item:
            if num not in frequency:
                frequency[num] = 0
            frequency[num] += 1

    return frequency

def snake_to_camel(snake_str: str) -> str:
    """Convert a snake_case string to camelCase."""
    if not snake_str:
        return snake_str

    # Remove underscores and convert to lowercase
    lower_snake = snake_str.lower()

    # Split by underscores and join with camelCase
    return "".join(word.capitalize() for word in lower_snake.split("_"))

def string_to_list(s: str) -> list[str]:
    """Convert a string to a list of strings split on the space character."""
    return s.split(" ")

def amicable_numbers_sum(n):
    """
    Sum all amicable numbers from 1 to n.

    An amicable pair is two distinct numbers that are equal in their 
    sum of proper divisors.

    Parameters:
    n (int): The upper bound for the sum (inclusive)

    Returns:
    int: Sum of all amicable numbers <= n
    """
    if n < 2:
        return 0

    # Precompute amicable numbers up to n
    amicable = set()
    for i in range(1, n + 1):
        if i in amicable:
            continue
        proper_divisors = [i]
        for d in range(2, i):
            if i % d == 0:
                proper_divisors.append(d)
        if len(proper_divisors) == 2:
            sum_proper = sum(proper_divisors)
            if sum_proper != i:
                amicable.add(i)

    return sum(amicable)

def reverse_vowels(s: str) -> str:
    vowels = set("aeiouAEIOU")
    result = []
    for char in s:
        if char in vowels:
            result.append(char)
        else:
            result.append(char)
    return "".join(result)

def tup_string(tup):
    """Convert a tuple to a string."""
    return "".join(str(item) for item in tup)

def count_occurance(s: str) -> int:
    """Count the number of occurrences of the substring 'std' in s."""
    return s.count("std")
